#code was generated by Claude AI

# merges everyone's replaced tweets, but handles two different file setups:
# "full" = someone sent back the WHOLE 50k file with just their rows replaced (like mine)
# "partial" = someone sent back ONLY their slice as its own small file (like liam and maggie)

import pandas as pd

ORIGINAL_PATH = "bot_detection_data.csv"
OUTPUT_PATH = "bot_detection_data_final.csv"

# note: these start/end numbers are pandas row positions (counting from 0),
# not the "row 1, row 2..." numbering you'd use counting by hand.
# vanshika's rows 1-12500 (by hand) = positions 0-12499 (in code)
TEAMMATE_SECTIONS = [
    {"name": "kavin",    "file": "bot_detection_data_kavin_share.csv", "start": 37500, "end": 50000, "format": "full"},
    {"name": "maggie",   "file": "maggie_second-_12500",                "start": 12500, "end": 25000, "format": "partial"},
    {"name": "vanshika", "file": "vanshika_share.csv",                 "start": 0,     "end": 12500, "format": "full"},  # change this once you get her file
    {"name": "liam",     "file": "liam_ollama_rows_25001_37500.csv",   "start": 25000, "end": 37500, "format": "partial"},
]

final = pd.read_csv(ORIGINAL_PATH)

for section in TEAMMATE_SECTIONS:
    teammate_df = pd.read_csv(section["file"])
    start, end = section["start"], section["end"]
    name = section["name"]

    if section["format"] == "full":
        # their file is the whole dataset, so just grab their chunk by the same row numbers
        final.loc[start:end-1, "Tweet"] = teammate_df.loc[start:end-1, "Tweet"].values
    else:
        # their file is JUST their slice, so it's already 0 to 12499 inside their own file
        # we just dump the whole thing into the right spot in the final file
        expected_rows = end - start
        if len(teammate_df) != expected_rows:
            print(f"WARNING: {name}'s file has {len(teammate_df)} rows, expected {expected_rows} — check this before trusting the merge")
            continue
        final.loc[start:end-1, "Tweet"] = teammate_df["Tweet"].values

    print(f"{name}: pasted rows {start} to {end-1} ({section['format']} format)")

final.to_csv(OUTPUT_PATH, index=False)
print(f"\nSaved merged file to {OUTPUT_PATH}")